selector_to_html = {"a[href=\"flagos-robo-user-guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagOS-Robo User Guide<a class=\"headerlink\" href=\"#flagos-robo-user-guide\" title=\"Link to this heading\">#</a></h1><h2>Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p>FlagOS-Robo is an integrated training and inference framework for AI models used in robots (Embodied Intelligence), built upon <a class=\"reference external\" href=\"https://flagos.io\">FlagOS</a>, the unified and open-source AI system software stack for various AI chips.</p><p>FlagOS-Robo can be deployed across diverse scenarios, ranging from edge to cloud. Being portable across various chip models, it enables efficient training, inference, and deployment for both Vision Language Models (VLMs) and Vision Language Action (VLA) models. VLMs usually act as the brain for task planning, while VLA models act as the cerebellum to output actions for robot control.</p>", "a[href=\"flagos-robo-user-guide.html#evaluation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Evaluation<a class=\"headerlink\" href=\"#evaluation\" title=\"Link to this heading\">#</a></h2><h3>FlagEval-Robo Platform<a class=\"headerlink\" href=\"#flageval-robo-platform\" title=\"Link to this heading\">#</a></h3><p>FlagOS-Robo integrates with the <a class=\"reference external\" href=\"https://embodiedverse.flageval.net/home\">FlagEval-Robo</a> platform for testing and evaluation of embodied intelligence models.</p>", "a[href=\"flagos-robo-user-guide.html#start-an-evaluation\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Start an Evaluation<a class=\"headerlink\" href=\"#start-an-evaluation\" title=\"Link to this heading\">#</a></h4><p>Key parameters:</p>", "a[href=\"flagos-robo-user-guide.html#roboxstudio-platform\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">RoboXStudio Platform<a class=\"headerlink\" href=\"#roboxstudio-platform\" title=\"Link to this heading\">#</a></h2><p>The <a class=\"reference external\" href=\"https://ei2data.baai.ac.cn/home\">RoboXStudio</a> platform provides a SaaS environment for the full embodied intelligence pipeline:</p>", "a[href=\"flagos-robo-user-guide.html#overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p>FlagOS-Robo is an integrated training and inference framework for AI models used in robots (Embodied Intelligence), built upon <a class=\"reference external\" href=\"https://flagos.io\">FlagOS</a>, the unified and open-source AI system software stack for various AI chips.</p><p>FlagOS-Robo can be deployed across diverse scenarios, ranging from edge to cloud. Being portable across various chip models, it enables efficient training, inference, and deployment for both Vision Language Models (VLMs) and Vision Language Action (VLA) models. VLMs usually act as the brain for task planning, while VLA models act as the cerebellum to output actions for robot control.</p>", "a[href=\"flagos-robo-user-guide.html#flageval-robo-platform\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">FlagEval-Robo Platform<a class=\"headerlink\" href=\"#flageval-robo-platform\" title=\"Link to this heading\">#</a></h3><p>FlagOS-Robo integrates with the <a class=\"reference external\" href=\"https://embodiedverse.flageval.net/home\">FlagEval-Robo</a> platform for testing and evaluation of embodied intelligence models.</p>", "a[href=\"flagos-robo-user-guide.html#getting-started\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">#</a></h2><h3>Supported Models<a class=\"headerlink\" href=\"#supported-models\" title=\"Link to this heading\">#</a></h3><p>For detailed guides on each model, refer to the <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagScale/tree/main/examples\">FlagScale examples</a>.</p>", "a[href=\"flagos-robo-user-guide.html#key-features\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Key Features<a class=\"headerlink\" href=\"#key-features\" title=\"Link to this heading\">#</a></h3>", "a[href=\"flagos-robo-user-guide.html#supported-models\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Supported Models<a class=\"headerlink\" href=\"#supported-models\" title=\"Link to this heading\">#</a></h3><p>For detailed guides on each model, refer to the <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagScale/tree/main/examples\">FlagScale examples</a>.</p>", "a[href=\"flagos-robo-user-guide.html#auto-evaluation-tool\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Auto-Evaluation Tool<a class=\"headerlink\" href=\"#auto-evaluation-tool\" title=\"Link to this heading\">#</a></h3><p>Auto-Evaluation is a multi-chip adaptive model automatic evaluation tool built on the <a class=\"reference external\" href=\"https://flageval.baai.ac.cn/#/home\">FlagEval</a> platform. It supports Embodied VLM models and is bound with ten classic datasets. Currently, it supports online evaluation only.</p><p><strong>Tool API Endpoint</strong>: <code class=\"docutils literal notranslate\"><span class=\"pre\">120.92.17.239:5050</span></code></p>", "a[href=\"#flagos-robo-documentation\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagOS-Robo Documentation<a class=\"headerlink\" href=\"#flagos-robo-documentation\" title=\"Link to this heading\">#</a></h1>", "a[href=\"flagos-robo-user-guide.html#available-apis\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Available APIs<a class=\"headerlink\" href=\"#available-apis\" title=\"Link to this heading\">#</a></h4>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
